        if version == 1:
            raise NoOldIdError()
        # A user-defined literal is a call to the corresponding literal
        # operator.  ``L_Z`` denotes an external-name expression in the
        # Itanium ABI expression grammar.
        operator = ASTOperatorLiteral(self.suffix)
        return 'clL_Z%sE%sE' % (operator.get_id(version),
                                self.literal.get_id(version))

